static int test_facts_v2_linkage_label_api_wrapper_promotes_code(void) {
  M68kObject object;
  M68kSection section;
  M68kFixup fixup;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  size_t index;
  int found_block = 0;
  int found_ref = 0;
  uint8_t bytes[0x24] = {
    0x4eu, 0x75u,
    0x00u, 0x00u, 0x00u, 0x08u,
    0x00u, 0x00u,
    0x2fu, 0x0eu,
    0x2cu, 0x79u, 0x00u, 0x00u, 0x00u, 0x20u,
    0x4eu, 0xaeu, 0xfdu, 0xd8u,
    0x2cu, 0x5fu,
    0x4eu, 0x75u,
    0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u,
    0x00u, 0x00u, 0x00u, 0x00u
  };
  M68K_C_ASSERT(platform_facts_v2_supports_linkage_api_entry_labels(M68K_PLATFORM_BACKEND_AMIGA_HUNK));
  M68K_C_ASSERT(!platform_facts_v2_supports_linkage_api_entry_labels(M68K_PLATFORM_BACKEND_ATARI_ST));
  M68K_C_ASSERT(platform_facts_v2_lvo_is_api(M68K_PLATFORM_BACKEND_AMIGA_HUNK, -552));
  M68K_C_ASSERT(!platform_facts_v2_lvo_is_api(M68K_PLATFORM_BACKEND_ATARI_ST, -552));
  memset(&section, 0, sizeof(section));
  memset(&source_analysis, 0, sizeof(source_analysis));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  memset(&fixup, 0, sizeof(fixup));
  fixup.section_index = 0U;
  fixup.offset = 2U;
  fixup.kind = M68K_FIXUP_ABS;
  fixup.width = M68K_FIXUP_WIDTH_32;
  fixup.has_target_section = 1;
  fixup.target_section_index = 0U;
  fixup.addend = 8;
  added = m68k_object_add_fixup(&object, &fixup);
  M68K_C_ASSERT(added.ok);
  fixup.offset = 12U;
  fixup.addend = 0x20;
  added = m68k_object_add_fixup(&object, &fixup);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_collect_source_analysis_profile(&object, &policy, &profile,
    &source_analysis, m68k_diag_sink(NULL)));
  M68K_C_ASSERT_U32(1U, (uint32_t)source_analysis.section_count);
  for (index = 0U; index < source_analysis.sections[0].block_count; ++index) {
    if (source_analysis.sections[0].blocks[index].start_offset == 8U) found_block = 1;
  }
  for (index = 0U; index < source_analysis.sections[0].code_start_ref_count; ++index) {
    const M68kCodeStartRefIR *ref = &source_analysis.sections[0].code_start_refs[index];
    if (ref->offset == 8U && ref->reason == M68K_FACT_CODE_START_REASON_LINKAGE_API_ENTRY) found_ref = 1;
  }
  M68K_C_ASSERT(found_block);
  M68K_C_ASSERT(found_ref);
  M68K_C_ASSERT_U32(1U, profile.code_start_linkage_api_entries);
  for (index = 0U; index < source_analysis.sections[0].orphan_code_signal_count; ++index) {
    M68K_C_ASSERT_U32(0U, source_analysis.sections[0].orphan_code_signals[index].offset == 8U);
  }
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

static int test_facts_v2_boundary_relocation_api_wrapper_promotes_code(void) {
  M68kObject object;
  M68kSection section;
  M68kFixup fixup;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  const AmigaOsLibraryVectorInfo *open_library =
    amiga_os_find_library_vector_by_symbol_id(AMIGA_OS_SYMBOL_ID_LVOOPENLIBRARY);
  size_t index;
  int found_block = 0;
  int found_ref = 0;
  int16_t lvo;
  char *source = NULL;
  uint8_t bytes[0x24];
  M68K_C_ASSERT(open_library != NULL);
  M68K_C_ASSERT(amiga_os_find_library_vector_by_ids(open_library->library_id,
    open_library->function_id, open_library->output.output_id) == open_library);
  M68K_C_ASSERT(amiga_os_find_library_vector_by_ids(open_library->library_id,
    open_library->function_id, (uint16_t)(open_library->output.output_id + 1U)) == NULL);
  lvo = open_library->lvo;
  memset(bytes, 0, sizeof(bytes));
  bytes[0] = 0x4eu;
  bytes[1] = 0x75u;
  bytes[2] = 0x2cu;
  bytes[3] = 0x79u;
  bytes[7] = 0x20u;
  bytes[8] = 0x72u;
  bytes[9] = 0x00u;
  bytes[10] = 0x4eu;
  bytes[11] = 0xeeu;
  bytes[12] = (uint8_t)(((uint16_t)lvo >> 8) & 0xffU);
  bytes[13] = (uint8_t)((uint16_t)lvo & 0xffU);
  memset(&section, 0, sizeof(section));
  memset(&source_analysis, 0, sizeof(source_analysis));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  memset(&fixup, 0, sizeof(fixup));
  fixup.section_index = 0U;
  fixup.offset = 4U;
  fixup.kind = M68K_FIXUP_ABS;
  fixup.width = M68K_FIXUP_WIDTH_32;
  fixup.has_target_section = 1;
  fixup.target_section_index = 0U;
  fixup.addend = 0x20;
  added = m68k_object_add_fixup(&object, &fixup);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "\tmovea.l loc_0_00000020.l,a6\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tjmp ") != NULL);
  M68K_C_ASSERT(strstr(source, "\tdc.b $2C,$79") == NULL);
  M68K_C_ASSERT_U32(1U, profile.code_start_boundary_api_entries);
  for (index = 0U; index < source_analysis.sections[0].block_count; ++index) {
    if (source_analysis.sections[0].blocks[index].start_offset == 2U) found_block = 1;
  }
  for (index = 0U; index < source_analysis.sections[0].code_start_ref_count; ++index) {
    const M68kCodeStartRefIR *ref = &source_analysis.sections[0].code_start_refs[index];
    if (ref->offset == 2U && ref->reason == M68K_FACT_CODE_START_REASON_BOUNDARY_API_ENTRY) found_ref = 1;
  }
  M68K_C_ASSERT(found_block);
  M68K_C_ASSERT(found_ref);
  for (index = 0U; index < source_analysis.sections[0].orphan_code_signal_count; ++index) {
    M68K_C_ASSERT_U32(0U, source_analysis.sections[0].orphan_code_signals[index].offset == 2U);
  }
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

static int test_facts_v2_boundary_relocation_api_call_restore_wrapper_promotes_code(void) {
  M68kObject object;
  M68kSection section;
  M68kFixup fixup;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  const AmigaOsLibraryVectorInfo *open_library =
    amiga_os_find_library_vector_by_symbol_id(AMIGA_OS_SYMBOL_ID_LVOOPENLIBRARY);
  size_t index;
  int found_block = 0;
  int found_ref = 0;
  int16_t lvo;
  char *source = NULL;
  uint8_t bytes[0x30];
  M68K_C_ASSERT(open_library != NULL);
  lvo = open_library->lvo;
  memset(bytes, 0, sizeof(bytes));
  bytes[0] = 0x4eu;
  bytes[1] = 0x75u;
  bytes[2] = 0x2fu;
  bytes[3] = 0x0eu;
  bytes[4] = 0x2cu;
  bytes[5] = 0x79u;
  bytes[9] = 0x24u;
  bytes[10] = 0x20u;
  bytes[11] = 0x2fu;
  bytes[13] = 0x08u;
  bytes[14] = 0x4eu;
  bytes[15] = 0xaeu;
  bytes[16] = (uint8_t)(((uint16_t)lvo >> 8) & 0xffU);
  bytes[17] = (uint8_t)((uint16_t)lvo & 0xffU);
  bytes[18] = 0x2cu;
  bytes[19] = 0x5fu;
  bytes[20] = 0x4eu;
  bytes[21] = 0x75u;
  memset(&section, 0, sizeof(section));
  memset(&source_analysis, 0, sizeof(source_analysis));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  memset(&fixup, 0, sizeof(fixup));
  fixup.section_index = 0U;
  fixup.offset = 6U;
  fixup.kind = M68K_FIXUP_ABS;
  fixup.width = M68K_FIXUP_WIDTH_32;
  fixup.has_target_section = 1;
  fixup.target_section_index = 0U;
  fixup.addend = 0x24;
  added = m68k_object_add_fixup(&object, &fixup);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "\tmove.l a6,-(a7)\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tmovea.l loc_0_00000024.l,a6\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tjsr ") != NULL);
  M68K_C_ASSERT(strstr(source, "\tmovea.l (a7)+,a6\n\trts\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tdc.b $2F,$0E,$2C,$79") == NULL);
  M68K_C_ASSERT_U32(1U, profile.code_start_boundary_api_entries);
  for (index = 0U; index < source_analysis.sections[0].block_count; ++index) {
    if (source_analysis.sections[0].blocks[index].start_offset == 2U) found_block = 1;
  }
  for (index = 0U; index < source_analysis.sections[0].code_start_ref_count; ++index) {
    const M68kCodeStartRefIR *ref = &source_analysis.sections[0].code_start_refs[index];
    if (ref->offset == 2U && ref->reason == M68K_FACT_CODE_START_REASON_BOUNDARY_API_ENTRY) found_ref = 1;
  }
  M68K_C_ASSERT(found_block);
  M68K_C_ASSERT(found_ref);
  for (index = 0U; index < source_analysis.sections[0].orphan_code_signal_count; ++index) {
    M68K_C_ASSERT_U32(0U, source_analysis.sections[0].orphan_code_signals[index].offset == 2U);
  }
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

