    "\tlea.l abs_0_00010028(pc),a0\n"
    "\tlea.l abs_0_00010000(pc),a1\n"
    "\tlea.l runtime_code_00000300.w,a2\n"
    "\tmoveq.l #41,d0\n"
    "abs_0_0001001E:\n"
    "\tmove.b (a0)+,(a2)+\n"
    "\tdbf.w d0,abs_0_0001001E\n"
    "\tjmp runtime_code_00000300.w\n"
    "abs_0_00010028:\n"
    "\trts\n";
