static int test_facts_v2_pc_index_loop_bound_promotes_exact_table_count(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  M68kRenderPlan source_plan;
  M68kRenderEvidenceIR render_evidence;
  char *source = NULL;
  const M68kTableConsumerIR *table_consumer = NULL;
  const M68kAddressExpressionIR *address_expression = NULL;
  const M68kRenderPlannedExpression *planned_expression;
  size_t index;
  uint8_t bytes[18] = {
    0x70u, 0x02u,
    0xd0u, 0xfbu, 0x00u, 0x08u,
    0x51u, 0xc8u, 0xffu, 0xfau,
    0x4eu, 0x75u,
    0x00u, 0x01u, 0x00u, 0x02u, 0x00u, 0x03u
  };
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  policy.entry_point_count = 1U;
  policy.entry_points[0].has_section_index = 1U;
  policy.entry_points[0].section_index = 0U;
  policy.entry_points[0].offset = 0U;
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_plan_analysis_profile_evidence_alloc(&object, &policy,
    &source, &source_plan, &profile, &source_analysis, &render_evidence, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "\tadda.w loc_0_0000000C(pc,d0.w),a0\n") != NULL);
  for (index = 0U; index < source_analysis.sections[0].table_consumer_count; ++index) {
    const M68kTableConsumerIR *consumer = &source_analysis.sections[0].table_consumers[index];
    if (consumer->table_start_offset == 12U &&
        consumer->source_pattern_id == M68K_ANALYSIS_STRUCTURED_DATA_SOURCE_PATTERN_PC_RELATIVE_INDEXED_READ) {
      table_consumer = consumer;
      break;
    }
  }
  M68K_C_ASSERT(table_consumer != NULL);
  M68K_C_ASSERT_U32(3U, table_consumer->entry_count);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_TABLE_ENTRY_COUNT_PROOF_LOOP_LIMIT, table_consumer->entry_count_proof_id);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_TABLE_STOP_REASON_LOOP_LIMIT_BOUND, table_consumer->table_stop_reason_id);
  M68K_C_ASSERT_U32(1U, table_consumer->has_index_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_DATA, table_consumer->index_register_kind);
  M68K_C_ASSERT_U32(0U, table_consumer->index_register);
  M68K_C_ASSERT_U32(1U, table_consumer->has_index_loop_domain);
  M68K_C_ASSERT_U32(0U, table_consumer->index_loop_min);
  M68K_C_ASSERT_U32(2U, table_consumer->index_loop_max);
  M68K_C_ASSERT_U32(M68K_ASM_MNEMONIC_DBF, table_consumer->index_loop_mnemonic_id);
  for (index = 0U; index < source_analysis.sections[0].address_expression_count; ++index) {
    const M68kAddressExpressionIR *expression = &source_analysis.sections[0].address_expressions[index];
    if (expression->base_offset == 12U) {
      address_expression = expression;
      break;
    }
  }
  M68K_C_ASSERT(address_expression != NULL);
  M68K_C_ASSERT_U32(M68K_ADDRESS_EXPRESSION_INDEXED_TABLE, address_expression->kind);
  M68K_C_ASSERT_U32(0U, address_expression->signed_addend);
  M68K_C_ASSERT_U32(2U, address_expression->element_stride);
  M68K_C_ASSERT_U32(0U, address_expression->index_register);
  planned_expression = m68k_render_plan_find_expression(&source_plan, 0U, 2U, 0U,
    M68K_RENDER_PLANNED_EXPRESSION_INSTRUCTION_OPERAND);
  M68K_C_ASSERT(planned_expression != NULL);
  M68K_C_ASSERT_U32(1U, planned_expression->has_address_expression);
  M68K_C_ASSERT_U32(address_expression->id, planned_expression->address_expression_id);
  M68K_C_ASSERT_U32(0U, planned_expression->address_expression_section_index);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  m68k_ir_render_evidence_destroy(&render_evidence);
  m68k_render_plan_destroy(&source_plan);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

