static int test_facts_v2_indexed_local_base_auto_classifies_pointer_table(void) {
  AsmSourceFile parsed_source;
  M68kObject object;
  M68kDiagList diagnostics;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  const M68kAnalysisStructuredDataItem *auto_item = NULL;
  const M68kAddressExpressionIR *address_expression = NULL;
  char *source = NULL;
  uint32_t data_ref_targets = 0U;
  uint16_t index;
  const char *source_text =
    "SECTION section_0,code\n"
    "start:\n"
    "\tbsr.s target0\n"
    "\tbsr.s target1\n"
    "\tlea.l table.l,a0\n"
    "\tmove.l $0(a0,d0.w),d1\n"
    "\trts\n"
    "target0:\n"
    "\trts\n"
    "target1:\n"
    "\trts\n"
    "table:\n"
    "\tdc.l $00000010,$00000012\n"
    "after:\n"
    "\trts\n";
  M68K_C_ASSERT_INT(0, m68k_source_model_create(&parsed_source));
  memset(&object, 0, sizeof(object));
  m68k_diag_list_reset(&diagnostics);
  parsed_source.target_cpu = M68K_ASM_CPU_68000;
  M68K_C_ASSERT(m68k_source_pipeline_parse_text_and_layout(&parsed_source, source_text,
    m68k_diag_sink(&diagnostics)));
  M68K_C_ASSERT_INT(1, m68k_source_pipeline_emit_object(&parsed_source, &object, m68k_diag_sink(&diagnostics)));
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "\tmove.l $0(a0,d0.w),d1\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tdc.l loc_0_00000010\t; pointer_table\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tdc.l loc_0_00000012\n") != NULL);
  for (index = 0U; index < source_analysis.structured_data_item_count; ++index) {
    const M68kAnalysisStructuredDataItem *item = &source_analysis.structured_data_items[index];
    if (item->has_section_index &&
        structured_data_item_has_role(item, M68K_ANALYSIS_STRUCTURED_DATA_ROLE_POINTER_TABLE)) {
      auto_item = item;
      break;
    }
  }
  M68K_C_ASSERT(auto_item != NULL);
  M68K_C_ASSERT_U32(1U, auto_item->has_index_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_DATA, auto_item->index_register_kind);
  M68K_C_ASSERT_U32(0U, auto_item->index_register);
  M68K_C_ASSERT_U32(1U, auto_item->has_target_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_DATA, auto_item->target_register_kind);
  M68K_C_ASSERT_U32(1U, auto_item->target_register);
  M68K_C_ASSERT_U32(8U, auto_item->size);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_STRUCTURED_DATA_LONGS, auto_item->kind);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_STRUCTURED_DATA_SOURCE_PATTERN_INDEXED_LOCAL_POINTER_READ,
    auto_item->source_pattern_id);
  M68K_C_ASSERT_U32(1U, (uint32_t)source_analysis.sections[0].address_expression_count);
  address_expression = &source_analysis.sections[0].address_expressions[0];
  M68K_C_ASSERT_U32(M68K_ADDRESS_EXPRESSION_INDEXED_TABLE, address_expression->kind);
  M68K_C_ASSERT_U32(0U, address_expression->consumer_section_index);
  M68K_C_ASSERT_U32(0U, address_expression->base_section_index);
  M68K_C_ASSERT_U32(auto_item->offset, address_expression->base_offset);
  M68K_C_ASSERT_U32(1U, address_expression->has_index_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_DATA, address_expression->index_register_kind);
  M68K_C_ASSERT_U32(0U, address_expression->index_register);
  M68K_C_ASSERT_U32(1U, address_expression->index_scale);
  M68K_C_ASSERT_U32(4U, address_expression->element_stride);
  for (index = 0U; index < source_analysis.sections[0].data_reference_count; ++index) {
    const M68kDataReferenceIR *ref = &source_analysis.sections[0].data_references[index];
    if (ref->source_kind == M68K_DATA_REFERENCE_SOURCE_TABLE_ENTRY &&
        ref->table_kind_id == M68K_ANALYSIS_TABLE_KIND_POINTER &&
        ref->table_start_offset == auto_item->offset) {
      if (ref->target_offset == 0x10U) data_ref_targets |= 1U;
      if (ref->target_offset == 0x12U) data_ref_targets |= 2U;
      M68K_C_ASSERT_U32(M68K_TABLE_ENTRY_TARGET_STATUS_ACCEPTED_TARGET, ref->target_status);
      M68K_C_ASSERT((ref->evidence_flags & M68K_DATA_REFERENCE_EVIDENCE_POINTER_TABLE) != 0U);
    }
  }
  M68K_C_ASSERT_U32(3U, data_ref_targets);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_byte_mismatches);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  m68k_source_model_free(&parsed_source);
  return 0;
}

