  accepted_starts[0] = certain_start;
  certain_start[0] = 1U;
  memset(&object_section, 0, sizeof(object_section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object_section.kind = M68K_SECTION_CODE;
