  M68K_C_ASSERT_INT(0, m68k_ir_section_analysis_append_symbol_origin(&target_section_analysis, &origin));
  origin.symbol_name = "addend_word";
  origin.offset = 10U;
  origin.source_offset = 10U;
  M68K_C_ASSERT_INT(0, m68k_ir_section_analysis_append_symbol_origin(&target_section_analysis, &origin));
