static int test_table_records_use_role_flags_not_text(void) {
  M68kSourceAnalysisIR source_analysis;
  M68kSectionAnalysisIR section_analysis;
  M68kAnalysisStructuredDataItem *item;
  char *analysis_json = NULL;
  memset(&source_analysis, 0, sizeof(source_analysis));
  memset(&section_analysis, 0, sizeof(section_analysis));
  m68k_analysis_policy_init_default(&source_analysis.policy);
  source_analysis.section_count = 1U;
  source_analysis.sections = &section_analysis;
  section_analysis.section_index = 0U;
  section_analysis.section_size = 8U;
  source_analysis.policy.structured_data_item_count = 2U;

  item = &source_analysis.policy.structured_data_items[0];
  item->has_section_index = 1U;
  item->section_index = 0U;
  item->offset = 0U;
  item->size = 4U;
  item->kind = M68K_ANALYSIS_STRUCTURED_DATA_WORDS;
  m68k_analysis_structured_data_item_set_semantic_role_flags(item,
    M68K_ANALYSIS_STRUCTURED_DATA_ROLE_LOOKUP_TABLE);
  item->source_pattern_id = M68K_ANALYSIS_STRUCTURED_DATA_SOURCE_PATTERN_INDEXED_WORD_DISPATCH;
  snprintf(item->source_pattern, sizeof(item->source_pattern), "%s", "stale_source_pattern");
  m68k_analysis_structured_data_item_refresh_table_metadata(item);

  item = &source_analysis.policy.structured_data_items[1];
  item->has_section_index = 1U;
  item->section_index = 0U;
  item->offset = 4U;
  item->size = 4U;
  item->kind = M68K_ANALYSIS_STRUCTURED_DATA_LONGS;
  snprintf(item->semantic_role, sizeof(item->semantic_role), "%s", "pointer_table");

  M68K_C_ASSERT_INT(0, source_analysis_to_json(&source_analysis, &analysis_json, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(analysis_json != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"table_record_count\":1") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"semantic_role\":\"lookup_table\",\"semantic_role_flags\":8") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"semantic_role\":\"pointer_table\"") == NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"source_pattern_id\":2,\"source_pattern\":\"indexed_word_dispatch\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "stale_source_pattern") == NULL);
  M68K_C_ASSERT(strstr(analysis_json,
    "\"role_flags\":8,\"role\":\"lookup_table\",\"table_kind_id\":1,\"table_kind\":\"scalar\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"role\":\"pointer_table\"") == NULL);
  free(analysis_json);
  return 0;
}

static int test_facts_v2_word_dispatch_stops_far_table_at_zero_boundary(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  uint8_t bytes[0x1046U];
  memset(bytes, 0, sizeof(bytes));
  bytes[0x00] = 0x43u;
  bytes[0x01] = 0xf9u;
  bytes[0x05] = 0x40u;
  bytes[0x06] = 0x41u;
  bytes[0x07] = 0xf9u;
  bytes[0x0b] = 0x20u;
  bytes[0x0c] = 0xd2u;
  bytes[0x0d] = 0xf0u;
  bytes[0x0e] = 0x10u;
  bytes[0x10] = 0x4eu;
  bytes[0x11] = 0xd1u;
  bytes[0x22] = 0x10u;
  bytes[0x23] = 0x02u;
  bytes[0x28] = 0x01u;
  bytes[0x29] = 0x00u;
  bytes[0x40] = 0x70u;
  bytes[0x41] = 0x01u;
  bytes[0x42] = 0x4eu;
  bytes[0x43] = 0x75u;
  bytes[0x1042] = 0x70u;
  bytes[0x1043] = 0x02u;
  bytes[0x1044] = 0x4eu;
  bytes[0x1045] = 0x75u;
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  memset(&source_analysis, 0, sizeof(source_analysis));
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source,
    "\tdc.w loc_0_00000040-loc_0_00000040\t; lookup_table\n"
    "\tdc.w loc_0_00001042-loc_0_00000040\n") != NULL);
  M68K_C_ASSERT(strstr(source, "loc_0_00000140:") == NULL);
  M68K_C_ASSERT(strstr(source, "\tdc.w loc_0_00000040-loc_0_00000040,loc_0_00000040-loc_0_00000040") == NULL);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_byte_mismatches);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

