  bytes[0x3e] = 0x2bu; bytes[0x3f] = 0x40u;
  bytes[0x42] = 0x20u; bytes[0x43] = 0x40u;
  bytes[0x44] = 0x4eu; bytes[0x45] = 0xb9u; bytes[0x48] = 0x01u; bytes[0x49] = 0x62u;
