static int test_facts_v2_source_analysis_retains_many_auto_structured_strings(void) {
  M68kObject object;
  M68kSection section;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  uint8_t *bytes = NULL;
  uint32_t offset = 0U, index, string_items = 0U;
  const uint32_t record_count = 300U;
  const uint32_t record_size = 6U;
  memset(&section, 0, sizeof(section));
  bytes = (uint8_t *)malloc(record_count * record_size);
  M68K_C_ASSERT(bytes != NULL);
  for (index = 0U; index < record_count; ++index) {
    bytes[offset++] = 'A';
    bytes[offset++] = (uint8_t)('A' + (index % 26U));
    bytes[offset++] = 'T';
    bytes[offset++] = 'X';
    bytes[offset++] = 'T';
    bytes[offset++] = 0U;
  }
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_DATA;
  section.size = offset;
  section.data_size = offset;
  section.data = bytes;
  M68K_C_ASSERT(m68k_object_add_section(&object, &section).ok);
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  for (index = 0U; index < m68k_ir_source_analysis_structured_data_item_count(&source_analysis); ++index) {
    const M68kAnalysisStructuredDataItem *item =
      m68k_ir_source_analysis_structured_data_item_at(&source_analysis, index);
    if (item != NULL && item->has_section_index && item->section_index == 0U &&
        structured_data_item_has_role(item, M68K_ANALYSIS_STRUCTURED_DATA_ROLE_STRING))
      ++string_items;
  }
  M68K_C_ASSERT_U32(record_count, string_items);
  M68K_C_ASSERT_U32(record_count, source_analysis.policy.structured_data_item_count);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  M68K_C_ASSERT_U32(M68K_SOURCE_EXPORT_FAILURE_NONE, profile.asm_source_first_failure_kind);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  free(bytes);
  return 0;
}

