  saw_rendered_second = test_render_evidence_has_symbol_access(&render_evidence, 0U, 6U, 0U,
    M68K_RENDERED_SYMBOL_ACCESS_EQUATE, "absolute_slot_0002F490", UINT32_MAX, 0U);
