static int test_facts_v2_render_asm_source_renders_call_input_domain_immediate(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  char *analysis_json = NULL;
  const AmigaOsLibraryVectorInfo *alert_vector = amiga_os_find_library_vector_by_symbol_name("_LVOAlert");
  int32_t an_icon_lib = 0;
  int32_t ag_open_lib = 0;
  int32_t ao_dos_lib = 0;
  uint32_t alert_value;
  int16_t alert_lvo;
  uint8_t bytes[14];
  M68K_C_ASSERT(alert_vector != NULL);
  M68K_C_ASSERT(amiga_os_find_constant_value("AN_IconLib", &an_icon_lib));
  M68K_C_ASSERT(amiga_os_find_constant_value("AG_OpenLib", &ag_open_lib));
  M68K_C_ASSERT(amiga_os_find_constant_value("AO_DOSLib", &ao_dos_lib));
  alert_value = (uint32_t)(an_icon_lib | ag_open_lib | ao_dos_lib);
  alert_lvo = alert_vector->lvo;
  bytes[0] = 0x2Eu;
  bytes[1] = 0x3Cu;
  bytes[2] = (uint8_t)(alert_value >> 24);
  bytes[3] = (uint8_t)(alert_value >> 16);
  bytes[4] = (uint8_t)(alert_value >> 8);
  bytes[5] = (uint8_t)alert_value;
  bytes[6] = 0x2Cu;
  bytes[7] = 0x78u;
  bytes[8] = 0x00u;
  bytes[9] = 0x04u;
  bytes[10] = 0x4Eu;
  bytes[11] = 0xAEu;
  bytes[12] = (uint8_t)((uint16_t)alert_lvo >> 8);
  bytes[13] = (uint8_t)alert_lvo;
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  object.platform_file_kind = M68K_PLATFORM_FILE_EXECUTABLE;
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source, &profile,
    &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "    INCLUDE \"exec/alerts.i\"\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tmove.l #AN_IconLib|AG_OpenLib|AO_DOSLib,d7\n") != NULL);
  M68K_C_ASSERT(strstr(source, "\tjsr _LVOAlert(a6)\n") != NULL);
  M68K_C_ASSERT_U32(1U, (uint32_t)source_analysis.section_count);
  {
    const M68kSectionAnalysisIR *analysis_section = &source_analysis.sections[0];
    int found_an = 0;
    int found_ag = 0;
    int found_ao = 0;
    int found_operand_expr_use = 0;
    size_t expected_index;
    size_t use_index;
    for (expected_index = 0U; expected_index < analysis_section->expected_symbol_access_count; ++expected_index) {
      const M68kExpectedSymbolAccessIR *expected = &analysis_section->expected_symbol_accesses[expected_index];
      if (expected->offset != 0U ||
          expected->operand_index != 0U ||
          expected->symbol_name == NULL ||
          expected->producer == NULL ||
          strcmp(expected->producer, "platform_call_input_value_domain_operand") != 0)
        continue;
      if (strcmp(expected->symbol_name, "AN_IconLib") == 0) found_an = 1;
      if (strcmp(expected->symbol_name, "AG_OpenLib") == 0) found_ag = 1;
      if (strcmp(expected->symbol_name, "AO_DOSLib") == 0) found_ao = 1;
    }
    for (use_index = 0U; use_index < analysis_section->platform_semantic_use_count; ++use_index) {
      const M68kPlatformSemanticUseIR *use = &analysis_section->platform_semantic_uses[use_index];
      if (use->kind == M68K_PLATFORM_SEMANTIC_USE_PLATFORM_CALL_INPUT &&
          use->offset == 0U &&
          use->has_operand_expr &&
          use->operand_index == 0U &&
          use->operand_expr != NULL &&
          strcmp(use->operand_expr, "AN_IconLib|AG_OpenLib|AO_DOSLib") == 0) {
        found_operand_expr_use = 1;
      }
    }
    M68K_C_ASSERT(found_an);
    M68K_C_ASSERT(found_ag);
    M68K_C_ASSERT(found_ao);
    M68K_C_ASSERT(found_operand_expr_use);
  }
  M68K_C_ASSERT_INT(0, source_analysis_to_json(&source_analysis, &analysis_json, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(analysis_json != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"kind_name\":\"platform_call_input\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"operand_index\":0") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"operand_expr\":\"AN_IconLib|AG_OpenLib|AO_DOSLib\"") != NULL);
  M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_byte_mismatches);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  free(analysis_json);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

