static int test_platform_canonical_row_batch_copies_borrowed_row_data(void) {
  PlatformCanonicalRowBatch batch;
  M68kRenderPlanRow row;
  char text[] = "loc_0_00000000:\n";
  size_t index;
  memset(&row, 0, sizeof(row));
  row.kind = M68K_RENDER_PLAN_ROW_LABEL;
  row.start_line = 7U;
  row.line_count = 1U;
  row.source_section_index = 3U;
  row.source_offset = 0x42U;
  row.runtime_address = 0x10042U;
  row.text = text;
  platform_canonical_row_batch_init(&batch);
  M68K_C_ASSERT_INT(0, platform_canonical_row_batch_append(&batch, &row));
  text[0] = 'X';
  memset(&row, 0, sizeof(row));
  M68K_C_ASSERT_U32(1U, (uint32_t)batch.count);
  M68K_C_ASSERT_U32(M68K_RENDER_PLAN_ROW_LABEL, batch.kinds[0]);
  M68K_C_ASSERT_U32(7U, batch.start_lines[0]);
  M68K_C_ASSERT_U32(1U, batch.line_counts[0]);
  M68K_C_ASSERT_U32(3U, batch.source_section_indices[0]);
  M68K_C_ASSERT_U32(0x42U, batch.source_offsets[0]);
  M68K_C_ASSERT_U32(0x10042U, batch.runtime_addresses[0]);
  M68K_C_ASSERT(strcmp(batch.texts[0], "loc_0_00000000:\n") == 0);
  for (index = 1U; index < PLATFORM_CANONICAL_ROW_BATCH_CAPACITY; ++index) {
    M68K_C_ASSERT_INT(0, platform_canonical_row_batch_append(&batch, &batch.render_rows[0]));
  }
  M68K_C_ASSERT(strcmp(batch.texts[0], "loc_0_00000000:\n") == 0);
  M68K_C_ASSERT(batch.render_rows[0].text == batch.texts[0]);
  M68K_C_ASSERT_INT(-1, platform_canonical_row_batch_append(&batch, &batch.render_rows[0]));
  platform_canonical_row_batch_destroy(&batch);
  return 0;
}

static int test_function_summary_effect_identities_are_canonical(void) {
  M68kFunctionSummaryAbiLocation location;
  M68kFunctionSummaryEffectSubjectIR subject;
  memset(&location, 0, sizeof(location));
  location.kind = M68K_FUNCTION_SUMMARY_ABI_LOCATION_REGISTER_TUPLE;
  location.width = 8U;
  location.register_count = 2U;
  location.registers[0].register_kind = M68K_ANALYSIS_REGISTER_DATA;
  location.registers[0].register_index = 0U;
  location.registers[1].register_kind = M68K_ANALYSIS_REGISTER_ADDRESS;
  location.registers[1].register_index = 0U;
  M68K_C_ASSERT(m68k_function_summary_abi_location_is_valid(&location));
  location.registers[0].register_kind = M68K_ANALYSIS_REGISTER_ADDRESS;
  location.registers[1].register_kind = M68K_ANALYSIS_REGISTER_DATA;
  M68K_C_ASSERT(!m68k_function_summary_abi_location_is_valid(&location));
  location.registers[0].register_kind = M68K_ANALYSIS_REGISTER_DATA;
  location.registers[1].register_kind = M68K_ANALYSIS_REGISTER_ADDRESS;
  location.register_count = 1U;
  M68K_C_ASSERT(!m68k_function_summary_abi_location_is_valid(&location));
  memset(&subject, 0, sizeof(subject));
  subject.kind = M68K_FUNCTION_SUMMARY_EFFECT_SUBJECT_INPUT;
  subject.input_index = 0U;
  M68K_C_ASSERT(m68k_function_summary_effect_subject_is_valid(&subject, 1U));
  subject.offset = 1U;
  M68K_C_ASSERT(!m68k_function_summary_effect_subject_is_valid(&subject, 1U));
  memset(&subject, 0, sizeof(subject));
  subject.kind = M68K_FUNCTION_SUMMARY_EFFECT_SUBJECT_STACK;
  subject.offset = 4U;
  subject.stack_convention = M68K_FUNCTION_SUMMARY_ABI_STACK_CALLER_ARGUMENT;
  M68K_C_ASSERT(m68k_function_summary_effect_subject_is_valid(&subject, 0U));
  subject.stack_convention = M68K_FUNCTION_SUMMARY_ABI_STACK_CALLER_RESULT;
  M68K_C_ASSERT(!m68k_function_summary_effect_subject_equal(&subject, &(M68kFunctionSummaryEffectSubjectIR){
    .kind = M68K_FUNCTION_SUMMARY_EFFECT_SUBJECT_STACK,
    .offset = 4U,
    .stack_convention = M68K_FUNCTION_SUMMARY_ABI_STACK_CALLER_ARGUMENT}));
  return 0;
}

